"use client"

import { motion } from "motion/react"

// Stand-in: imports motion/react although the item declares no dependencies.
export const Spotlight = ({ duration = 6 }: { duration?: number } = {}) => {
  return (
    <motion.div className="pointer-events-none absolute inset-0" animate={{ x: [0, 80, 0] }} transition={{ duration, repeat: Infinity }}>
      <div className="absolute size-96 rounded-full" style={{ background: "radial-gradient(circle, hsla(210, 90%, 80%, .1), transparent 70%)" }} />
    </motion.div>
  )
}
